'use client';

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getCategories } from '@/api/category';
import ProductList from '@/components/product/ProductList';

export default function Home() {
  const [selectedCategories, setSelectedCategories] = useState<string[]>([]);

  const { data: categories, isLoading: loadingCategories } = useQuery({
    queryKey: ['categories'],
    queryFn: () => getCategories(true),
  });

  const handleCategoryChange = (categoryId: string) => {
    setSelectedCategories(prev =>
      prev.includes(categoryId)
        ? prev.filter(id => id !== categoryId)
        : [...prev, categoryId]
    );
  };

  return (
    <div className="min-h-screen bg-white">
      {/* Header */}
      <header className="border-b">
        <div className="max-w-7xl mx-auto px-8 py-4 flex items-center justify-between">
          <div className="text-xl font-bold">INTERNSHOP</div>
          <div className="flex items-center gap-6">
            <input
              type="text"
              placeholder="Tìm sản phẩm..."
              className="w-64 px-4 py-2 border rounded-lg text-sm"
            />
            <nav className="flex items-center gap-6 text-sm">
              <span className="cursor-pointer hover:text-blue-600">Trang chủ</span>
              <span className="cursor-pointer hover:text-blue-600">All Product</span>
              <span className="cursor-pointer hover:text-blue-600">Cart (0)</span>
              <span className="cursor-pointer hover:text-blue-600">Login</span>
            </nav>
          </div>
        </div>
      </header>

      {/* Hero Banner */}
      <div className="h-72 bg-gradient-to-r from-blue-500 to-purple-600 flex items-center justify-center">
        <h1 className="text-4xl font-bold text-white">Welcome to INTERNSHOP</h1>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-8 py-8">
        <div className="grid grid-cols-[240px_1fr] gap-6">
          {/* Left Sidebar - Filters */}
          <aside className="bg-gray-50 p-4 rounded-lg border border-gray-200">
            <h3 className="font-semibold text-sm mb-4 text-gray-800">FILTERS</h3>
            <div className="mb-6">
              <h4 className="text-xs font-semibold text-gray-600 mb-2">CATEGORY</h4>
              <div className="text-sm text-gray-700 space-y-1">
                {loadingCategories ? (
                  <span className="text-gray-400">Loading...</span>
                ) : (
                  categories?.data?.map((category: { id: number; name: string }) => (
                    <label
                      key={category.id}
                      className={`flex items-center gap-2 cursor-pointer ${selectedCategories.includes(String(category.id)) ? 'text-blue-600 font-medium' : ''}`}
                    >
                      <input
                        type="checkbox"
                        checked={selectedCategories.includes(String(category.id))}
                        onChange={() => handleCategoryChange(String(category.id))}
                        className="rounded"
                      />
                      <span>{category.name}</span>
                    </label>
                  ))
                )}
              </div>
            </div>
            <div>
              <h4 className="text-xs font-semibold text-gray-600 mb-2">PRICE RANGE</h4>
              <input
                type="text"
                placeholder="0đ - 2.000.000đ"
                className="w-full border rounded px-3 py-2 text-sm"
              />
            </div>
          </aside>

          {/* Product Grid */}
          <main>
            <ProductList categoryIds={selectedCategories} />
          </main>
        </div>
      </div>
    </div>
  );
}
